INSERT OR IGNORE INTO wb_programs (id, code, slug, name_vi, language_code, program_type, specialized_domain_slug, entry_level, target_level, target_audience, prerequisites, total_modules, total_weeks, sessions_per_week, estimated_hours, overall_objectives, learning_outcomes, focus_skills_json, assessment_methods, completion_criteria, review_status, author_name, reviewer_name, reference_sources) VALUES ('prg_zh_fnd', 'WB-ZH-FND-01', 'chinese-foundation-hsk1', 'Tiếng Trung Nền tảng (Tham chiếu HSK 1)', 'zh', 'foundation', NULL, 'Mới bắt đầu', 'Tham chiếu HSK 1', 'Người học Việt Nam bắt đầu từ con số 0', 'Không yêu cầu', 3, 12, 3, 48, 'Xây dựng nền tảng Pinyin, thanh điệu, 150+ từ vựng cốt lõi và giao tiếp cơ bản.', 'Đọc viết Pinyin chuẩn, nhận diện chữ Hán nền tảng, giao tiếp 12 chủ đề đời sống.', '["listening","speaking","reading","writing"]', 'Kiểm tra cuối tuần + Đánh giá tích hợp tuần 12', 'Hoàn thành >= 80% bài học và đạt >= 70% bài đánh giá tuần 12', 'published', 'Ban Biên soạn Học thuật WORD BRIDGE', 'Hội đồng Rà soát Học thuật WORD BRIDGE', 'Khung giáo trình chuẩn WORD BRIDGE V3.0');
INSERT OR IGNORE INTO wb_programs (id, code, slug, name_vi, language_code, program_type, specialized_domain_slug, entry_level, target_level, target_audience, prerequisites, total_modules, total_weeks, sessions_per_week, estimated_hours, overall_objectives, learning_outcomes, focus_skills_json, assessment_methods, completion_criteria, review_status, author_name, reviewer_name, reference_sources) VALUES ('prg_en_fnd', 'WB-EN-FND-01', 'english-foundation-a1', 'Tiếng Anh Nền tảng (Tham chiếu CEFR A1)', 'en', 'foundation', NULL, 'Mới bắt đầu', 'Tham chiếu CEFR A1', 'Người học cần củng cố phát âm IPA và giao tiếp căn bản', 'Không yêu cầu', 3, 12, 3, 48, 'Làm chủ hệ thống âm IPA, thì hiện tại/quá khứ/tương lai cơ bản và 12 tình huống đời sống.', 'Phát âm rõ âm cuối, giao tiếp chủ đề quen thuộc, viết đoạn ngắn mạch lạc.', '["listening","speaking","reading","writing"]', 'Bài tập 4 kỹ năng hằng tuần + Đánh giá tổng hợp tuần 12', 'Hoàn thành >= 80% buổi học và đạt >= 70% bài đánh giá tổng hợp', 'published', 'Ban Biên soạn Học thuật WORD BRIDGE', 'Hội đồng Rà soát Học thuật WORD BRIDGE', 'Khung giáo trình chuẩn WORD BRIDGE V3.0');
INSERT OR IGNORE INTO wb_programs (id, code, slug, name_vi, language_code, program_type, specialized_domain_slug, entry_level, target_level, target_audience, prerequisites, total_modules, total_weeks, sessions_per_week, estimated_hours, overall_objectives, learning_outcomes, focus_skills_json, assessment_methods, completion_criteria, review_status, author_name, reviewer_name, reference_sources) VALUES ('prg_ru_fnd', 'WB-RU-FND-01', 'russian-foundation-teu', 'Tiếng Nga Nền tảng (Tham chiếu TORFL ТЭУ)', 'ru', 'foundation', NULL, 'Mới bắt đầu', 'Tham chiếu TORFL ТЭУ', 'Người học tiếng Nga sơ cấp', 'Không yêu cầu', 3, 12, 3, 54, 'Làm chủ bảng chữ cái Cyrillic, trọng âm, biến âm, giống danh từ và các cách nền tảng (1, 4, 6).', 'Đọc đúng trọng âm tiếng Nga, sử dụng chính xác Cách 1/4/6 và hội thoại căn bản.', '["listening","speaking","reading","writing"]', 'Bài kiểm tra tuần + Đánh giá 4 kỹ năng tuần 12', 'Hoàn thành >= 80% buổi học và đạt >= 70% bài đánh giá tuần 12', 'published', 'Ban Biên soạn Học thuật WORD BRIDGE', 'Hội đồng Rà soát Học thuật WORD BRIDGE', 'Khung giáo trình chuẩn WORD BRIDGE V3.0');
INSERT OR IGNORE INTO wb_programs (id, code, slug, name_vi, language_code, program_type, specialized_domain_slug, entry_level, target_level, target_audience, prerequisites, total_modules, total_weeks, sessions_per_week, estimated_hours, overall_objectives, learning_outcomes, focus_skills_json, assessment_methods, completion_criteria, review_status, author_name, reviewer_name, reference_sources) VALUES ('prg_zh_log', 'WB-ZH-SPC-LOG', 'chinese-specialized-logistics', 'Tiếng Trung Chuyên ngành Logistics & Xuất nhập khẩu', 'zh', 'specialized', 'logistics', 'HSK 3+', 'Giao tiếp nghiệp vụ Logistics', 'Nhân sự xuất nhập khẩu, vận tải biển, chuỗi cung ứng', 'Hoàn thành tiếng Trung sơ cấp', 2, 8, 3, 36, 'Làm chủ thuật ngữ vận đơn, khai báo hải quan, chứng từ thương mại và đàm phán đối tác Trung Quốc.', 'Đọc hiểu vận đơn (海运提单), hóa đơn thương mại (商业发票), viết email nghiệp vụ và xử lý tình huống kho vận.', '["listening","speaking","reading","writing"]', 'Tình huống chứng từ thực tế + Viết email nghiệp vụ', 'Hoàn thành bài tập chứng từ và đạt >= 75% đánh giá chuyên ngành', 'published', 'Ban Biên soạn Học thuật WORD BRIDGE', 'Hội đồng Rà soát Học thuật WORD BRIDGE', 'Khung giáo trình chuẩn WORD BRIDGE V3.0');
INSERT OR IGNORE INTO wb_programs (id, code, slug, name_vi, language_code, program_type, specialized_domain_slug, entry_level, target_level, target_audience, prerequisites, total_modules, total_weeks, sessions_per_week, estimated_hours, overall_objectives, learning_outcomes, focus_skills_json, assessment_methods, completion_criteria, review_status, author_name, reviewer_name, reference_sources) VALUES ('prg_en_it', 'WB-EN-SPC-IT', 'english-specialized-it-cloud', 'Tiếng Anh Chuyên ngành CNTT & Cloud', 'en', 'specialized', 'it-cloud', 'CEFR B1', 'Giao tiếp kỹ thuật CNTT B2+', 'Kỹ sư phần mềm, quản trị mạng, Cloud engineer', 'Nền tảng tiếng Anh giao tiếp cơ bản', 2, 8, 3, 36, 'Đọc tài liệu kiến trúc hệ thống, báo cáo sự cố, viết tài liệu kỹ thuật và thuyết trình giải pháp Cloud.', 'Sử dụng chuẩn thuật ngữ mạng/Cloud, viết incident report và trình bày kiến trúc bằng tiếng Anh.', '["listening","speaking","reading","writing"]', 'Đọc tài liệu kỹ thuật + Viết báo cáo sự cố', 'Hoàn thành 100% bài tập tình huống và đạt >= 75% bài kiểm tra chuyên ngành', 'published', 'Ban Biên soạn Học thuật WORD BRIDGE', 'Hội đồng Rà soát Học thuật WORD BRIDGE', 'Khung giáo trình chuẩn WORD BRIDGE V3.0');

