INSERT OR IGNORE INTO wb_modules (id, course_id, slug, title_vi, sort_order, objectives_vi) VALUES ('mod_ru_1', 'crs_ru_1', 'russian-beginner-module-1', 'Học phần 1: Bảng chữ cái Cyrillic, Trọng âm & Hệ thống Cách cơ bản', 1, 'Nắm vững hệ thống âm vị, từ vựng cốt lõi và cấu trúc câu giao tiếp căn bản.');
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_01', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-01', 1, 'Tuần 01: Pinyin và thanh điệu', 'Pinyin và thanh điệu', 'Làm chủ chủ đề ''Pinyin và thanh điệu'' với trọng tâm: Thanh mẫu, vận mẫu, bốn thanh, thanh nhẹ, chào hỏi.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 1 trong giao tiếp thực tế.', 'Thanh mẫu, vận mẫu, bốn thanh, thanh nhẹ, chào hỏi', '["你好 (nǐ hǎo)", "谢谢 (xièxie)", "再见 (zàijiàn)"]', '["Cấu trúc chào hỏi cơ bản", "Biến điệu thanh 3 (3+3 → 2+3)"]', 'Phân biệt thanh mẫu b/p/m/f, d/t/n/l và 4 thanh điệu + thanh nhẹ', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Pinyin và thanh điệu (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Pinyin và thanh điệu.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Pinyin và thanh điệu.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 1.', 'Tình huống giao tiếp thực tế gắn với chủ đề Pinyin và thanh điệu trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 01", "Phiếu luyện viết tuần 01"]', '["audio/zh/week-01-dialogue.mp3"]', '["Bài tập từ vựng tuần 01", "Bài tập ngữ pháp tuần 01", "Bài tập nghe hiểu tuần 01"]', 'Bài kiểm tra định kỳ cuối tuần 01 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 01.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 02.', 3);
INSERT OR IGNORE INTO wb_study_sessions (id, week_id, session_code, title_vi, position_in_week, duration_minutes, objectives, new_knowledge, vocabulary_json, grammar_json, pronunciation_notes, examples_json, materials_json, activities_json, short_exercises_json, comprehension_check_json, summary_text, self_study_homework, completion_condition) VALUES ('ses_zh_01_1', 'wk_zh_01', 'ZH-W01-S1', 'Buổi 1 — Pinyin và thanh điệu', 1, 45, 'Nắm vững nền tảng Pinyin và thanh điệu', 'Thanh mẫu, vận mẫu, bốn thanh, thanh nhẹ, chào hỏi', '["你好 (nǐ hǎo)", "谢谢 (xièxie)", "再见 (zàijiàn)"]', '["Cấu trúc chào hỏi cơ bản", "Biến điệu thanh 3 (3+3 → 2+3)"]', 'Phân biệt thanh mẫu b/p/m/f, d/t/n/l và 4 thanh điệu + thanh nhẹ', '["Ví dụ 1","Ví dụ 2"]', '["Slide bài giảng","Phiếu bài tập"]', '["Nghe mẫu","Thực hành cặp","Kiểm tra nhanh"]', '["Điền từ","Sắp xếp câu"]', '["Câu hỏi kiểm tra hiểu bài"]', 'Tổng kết trọng tâm Pinyin và thanh điệu.', 'Ôn tập 15 phút trên Sổ từ vựng WORD BRIDGE.', 'Hoàn thành bài tập ngắn và đạt >= 70% kiểm tra mức hiểu.');
INSERT OR IGNORE INTO wb_lessons (id, session_id, week_id, slug, title_vi, language_code, level_ref, is_public_preview, components_json, author_name, reviewer_name, reference_sources, version, review_status) VALUES ('les_zh_01_1', 'ses_zh_01_1', 'wk_zh_01', 'chinese-week-01-lesson-01', 'Bài 1 (Tuần 01: Pinyin và thanh điệu)', 'zh', 'HSK 1', 1, '{"objectives": "Nắm vững kiến thức cốt lõi của Tuần 01: Pinyin và thanh điệu.", "coreKnowledge": "Thanh mẫu, vận mẫu, bốn thanh, thanh nhẹ, chào hỏi", "newVocabulary": ["你好 (nǐ hǎo)", "谢谢 (xièxie)", "再见 (zàijiàn)"], "grammar": ["Cấu trúc chào hỏi cơ bản", "Biến điệu thanh 3 (3+3 → 2+3)"], "phonetics": "Phân biệt thanh mẫu b/p/m/f, d/t/n/l và 4 thanh điệu + thanh nhẹ", "examples": ["Ví dụ ứng dụng chuẩn cho chủ đề Pinyin và thanh điệu."], "context": "Bối cảnh giao tiếp thực tế cho Pinyin và thanh điệu.", "listening": "Nghe đoạn mẫu chủ đề Pinyin và thanh điệu và trả lời 3 câu hỏi kiểm tra ý chính.", "speaking": "Đọc theo câu mẫu với tốc độ 0.75x rồi 1.0x; tự luyện phát âm qua microphone khi chủ động bật.", "reading": "Đọc đoạn văn ngắn minh họa và gạch chân cấu trúc trọng tâm.", "writing": "Viết 5 câu hoàn chỉnh vận dụng từ vựng và ngữ pháp tuần 01.", "assessment": "Kiểm tra mức hiểu cuối bài (5 câu hỏi nhanh)."}', 'Ban Biên soạn WORD BRIDGE', 'Hội đồng Học thuật WORD BRIDGE', 'Giáo trình chuẩn WORD BRIDGE V3.0', '1.0.0', 'published');
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_02', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-02', 2, 'Tuần 02: Làm quen và giới thiệu', 'Làm quen và giới thiệu', 'Làm chủ chủ đề ''Làm quen và giới thiệu'' với trọng tâm: Đại từ, tên, quốc tịch, câu giới thiệu.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 2 trong giao tiếp thực tế.', 'Đại từ, tên, quốc tịch, câu giới thiệu', '["我 (wǒ)", "你 (nǐ)", "叫 (jiào)", "越南 (Yuènán)"]', '["S + 叫 + Tên", "S + 是 + Quốc tịch"]', 'Ngữ điệu câu giới thiệu và biến điệu 不 (bù)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Làm quen và giới thiệu (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Làm quen và giới thiệu.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Làm quen và giới thiệu.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 2.', 'Tình huống giao tiếp thực tế gắn với chủ đề Làm quen và giới thiệu trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 02", "Phiếu luyện viết tuần 02"]', '["audio/zh/week-02-dialogue.mp3"]', '["Bài tập từ vựng tuần 02", "Bài tập ngữ pháp tuần 02", "Bài tập nghe hiểu tuần 02"]', 'Bài kiểm tra định kỳ cuối tuần 02 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 02.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 03.', 3);
