INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_03', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-03', 3, 'Tuần 03: Số đếm và thông tin cá nhân', 'Số đếm và thông tin cá nhân', 'Làm chủ chủ đề ''Số đếm và thông tin cá nhân'' với trọng tâm: Số, tuổi, số điện thoại, ngày tháng.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 3 trong giao tiếp thực tế.', 'Số, tuổi, số điện thoại, ngày tháng', '["一 đến 十", "岁 (suì)", "电话 (diànhuà)", "月/号"]', '["Hỏi tuổi với 几岁 / 多大", "Đọc số điện thoại (1 đọc là yāo)"]', 'Phân biệt âm bật hơi q/ch/c và số đếm liên tiếp', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Số đếm và thông tin cá nhân (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Số đếm và thông tin cá nhân.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Số đếm và thông tin cá nhân.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 3.', 'Tình huống giao tiếp thực tế gắn với chủ đề Số đếm và thông tin cá nhân trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 03", "Phiếu luyện viết tuần 03"]', '["audio/zh/week-03-dialogue.mp3"]', '["Bài tập từ vựng tuần 03", "Bài tập ngữ pháp tuần 03", "Bài tập nghe hiểu tuần 03"]', 'Bài kiểm tra định kỳ cuối tuần 03 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 03.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 04.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_04', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-04', 4, 'Tuần 04: Gia đình và quan hệ', 'Gia đình và quan hệ', 'Làm chủ chủ đề ''Gia đình và quan hệ'' với trọng tâm: Từ vựng gia đình, lượng từ cơ bản, sở hữu.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 4 trong giao tiếp thực tế.', 'Từ vựng gia đình, lượng từ cơ bản, sở hữu', '["家 (jiā)", "爸爸 (bàba)", "妈妈 (māma)", "口 (kǒu)"]', '["Sở hữu với 的", "Lượng từ 口, 个"]', 'Thanh nhẹ trong từ lặp gia đình (bàba, māma)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Gia đình và quan hệ (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Gia đình và quan hệ.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Gia đình và quan hệ.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 4.', 'Tình huống giao tiếp thực tế gắn với chủ đề Gia đình và quan hệ trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 04", "Phiếu luyện viết tuần 04"]', '["audio/zh/week-04-dialogue.mp3"]', '["Bài tập từ vựng tuần 04", "Bài tập ngữ pháp tuần 04", "Bài tập nghe hiểu tuần 04"]', 'Bài kiểm tra định kỳ cuối tuần 04 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 04.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 05.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_05', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-05', 5, 'Tuần 05: Trường học và công việc', 'Trường học và công việc', 'Làm chủ chủ đề ''Trường học và công việc'' với trọng tâm: Nghề nghiệp, địa điểm, câu hỏi thông tin.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 5 trong giao tiếp thực tế.', 'Nghề nghiệp, địa điểm, câu hỏi thông tin', '["学生 (xuésheng)", "老师 (lǎoshī)", "工作 (gōngzuò)", "公司 (gōngsī)"]', '["Câu hỏi với 什么, 哪儿", "Động từ 在 + địa điểm"]', 'Âm uốn lưỡi zh/ch/sh/r', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Trường học và công việc (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Trường học và công việc.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Trường học và công việc.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 5.', 'Tình huống giao tiếp thực tế gắn với chủ đề Trường học và công việc trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 05", "Phiếu luyện viết tuần 05"]', '["audio/zh/week-05-dialogue.mp3"]', '["Bài tập từ vựng tuần 05", "Bài tập ngữ pháp tuần 05", "Bài tập nghe hiểu tuần 05"]', 'Bài kiểm tra định kỳ cuối tuần 05 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 05.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 06.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_06', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-06', 6, 'Tuần 06: Thời gian và lịch trình', 'Thời gian và lịch trình', 'Làm chủ chủ đề ''Thời gian và lịch trình'' với trọng tâm: Giờ, ngày, lịch học, trạng từ thời gian.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 6 trong giao tiếp thực tế.', 'Giờ, ngày, lịch học, trạng từ thời gian', '["点 (diǎn)", "分 (fēn)", "今天 (jīntiān)", "星期 (xīngqī)"]', '["Trạng từ thời gian đứng trước động từ", "Cách nói giờ kém/hơn"]', 'Nhịp điệu đọc ngày tháng và khung giờ', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Thời gian và lịch trình (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Thời gian và lịch trình.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Thời gian và lịch trình.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 6.', 'Tình huống giao tiếp thực tế gắn với chủ đề Thời gian và lịch trình trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 06", "Phiếu luyện viết tuần 06"]', '["audio/zh/week-06-dialogue.mp3"]', '["Bài tập từ vựng tuần 06", "Bài tập ngữ pháp tuần 06", "Bài tập nghe hiểu tuần 06"]', 'Bài kiểm tra định kỳ cuối tuần 06 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 06.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 07.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_07', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-07', 7, 'Tuần 07: Ăn uống và mua sắm', 'Ăn uống và mua sắm', 'Làm chủ chủ đề ''Ăn uống và mua sắm'' với trọng tâm: Món ăn, giá tiền, lượng từ, giao dịch.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 7 trong giao tiếp thực tế.', 'Món ăn, giá tiền, lượng từ, giao dịch', '["多少钱 (duōshao qián)", "块 (kuài)", "买 (mǎi)", "喝茶 (hē chá)"]', '["Hỏi giá với 多少钱", "Cấu trúc 要 / 想买"]', 'Phân biệt thanh 3 trong 买 (mǎi) và thanh 4 trong 卖 (mài)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Ăn uống và mua sắm (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Ăn uống và mua sắm.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Ăn uống và mua sắm.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 7.', 'Tình huống giao tiếp thực tế gắn với chủ đề Ăn uống và mua sắm trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 07", "Phiếu luyện viết tuần 07"]', '["audio/zh/week-07-dialogue.mp3"]', '["Bài tập từ vựng tuần 07", "Bài tập ngữ pháp tuần 07", "Bài tập nghe hiểu tuần 07"]', 'Bài kiểm tra định kỳ cuối tuần 07 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 07.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 08.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_08', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-08', 8, 'Tuần 08: Địa điểm và phương hướng', 'Địa điểm và phương hướng', 'Làm chủ chủ đề ''Địa điểm và phương hướng'' với trọng tâm: Vị trí, phương tiện, hỏi đường.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 8 trong giao tiếp thực tế.', 'Vị trí, phương tiện, hỏi đường', '["前面 (qiánmiàn)", "左边 (zuǒbiān)", "坐车 (zuò chē)", "怎么走"]', '["A 在 B 的 + phương vị từ", "Hỏi đường với 怎么走"]', 'Phát âm vận mẫu mũi -n và -ng', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Địa điểm và phương hướng (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Địa điểm và phương hướng.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Địa điểm và phương hướng.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 8.', 'Tình huống giao tiếp thực tế gắn với chủ đề Địa điểm và phương hướng trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 08", "Phiếu luyện viết tuần 08"]', '["audio/zh/week-08-dialogue.mp3"]', '["Bài tập từ vựng tuần 08", "Bài tập ngữ pháp tuần 08", "Bài tập nghe hiểu tuần 08"]', 'Bài kiểm tra định kỳ cuối tuần 08 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 08.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 09.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_09', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-09', 9, 'Tuần 09: Sinh hoạt thường ngày', 'Sinh hoạt thường ngày', 'Làm chủ chủ đề ''Sinh hoạt thường ngày'' với trọng tâm: Động từ thường dùng, cấu trúc câu cơ bản.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 9 trong giao tiếp thực tế.', 'Động từ thường dùng, cấu trúc câu cơ bản', '["起床 (qǐchuáng)", "上班 (shàngbān)", "睡觉 (shuìjiào)"]', '["Trật tự câu Thời gian + Địa điểm + Động từ", "Phó từ 常/每天"]', 'Nối âm tự nhiên trong câu kể lịch trình', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Sinh hoạt thường ngày (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Sinh hoạt thường ngày.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Sinh hoạt thường ngày.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 9.', 'Tình huống giao tiếp thực tế gắn với chủ đề Sinh hoạt thường ngày trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 09", "Phiếu luyện viết tuần 09"]', '["audio/zh/week-09-dialogue.mp3"]', '["Bài tập từ vựng tuần 09", "Bài tập ngữ pháp tuần 09", "Bài tập nghe hiểu tuần 09"]', 'Bài kiểm tra định kỳ cuối tuần 09 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 09.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 10.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_10', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-10', 10, 'Tuần 10: Sở thích và khả năng', 'Sở thích và khả năng', 'Làm chủ chủ đề ''Sở thích và khả năng'' với trọng tâm: 想, 会, 能, 喜欢 và các cấu trúc phù hợp.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 10 trong giao tiếp thực tế.', '想, 会, 能, 喜欢 và các cấu trúc phù hợp', '["喜欢 (xǐhuan)", "会 (huì)", "能 (néng)", "想 (xiǎng)"]', '["Phân biệt động từ năng nguyện 想 / 会 / 能", "Câu hỏi chính phản"]', 'Nhấn trọng âm vào động từ năng nguyện', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Sở thích và khả năng (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Sở thích và khả năng.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Sở thích và khả năng.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 10.', 'Tình huống giao tiếp thực tế gắn với chủ đề Sở thích và khả năng trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 10", "Phiếu luyện viết tuần 10"]', '["audio/zh/week-10-dialogue.mp3"]', '["Bài tập từ vựng tuần 10", "Bài tập ngữ pháp tuần 10", "Bài tập nghe hiểu tuần 10"]', 'Bài kiểm tra định kỳ cuối tuần 10 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 10.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 11.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_11', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-11', 11, 'Tuần 11: Sức khỏe và nhu cầu', 'Sức khỏe và nhu cầu', 'Làm chủ chủ đề ''Sức khỏe và nhu cầu'' với trọng tâm: Bộ phận cơ thể, triệu chứng cơ bản, lời khuyên.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 11 trong giao tiếp thực tế.', 'Bộ phận cơ thể, triệu chứng cơ bản, lời khuyên', '["身体 (shēntǐ)", "头疼 (tóuténg)", "医生 (yīshēng)", "休息 (xiūxi)"]', '["Trợ từ 了 biểu thị thay đổi trạng thái", "Khuyên nhủ với 应该 / 多"]', 'Ngữ điệu quan tâm và hỏi thăm sức khỏe', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Sức khỏe và nhu cầu (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Sức khỏe và nhu cầu.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Sức khỏe và nhu cầu.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 11.', 'Tình huống giao tiếp thực tế gắn với chủ đề Sức khỏe và nhu cầu trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 11", "Phiếu luyện viết tuần 11"]', '["audio/zh/week-11-dialogue.mp3"]', '["Bài tập từ vựng tuần 11", "Bài tập ngữ pháp tuần 11", "Bài tập nghe hiểu tuần 11"]', 'Bài kiểm tra định kỳ cuối tuần 11 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 11.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 12.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_zh_12', 'mod_zh_1', 'crs_zh_1', 'chinese-beginner-week-12', 12, 'Tuần 12: Tổng ôn và đánh giá', 'Tổng ôn và đánh giá', 'Làm chủ chủ đề ''Tổng ôn và đánh giá'' với trọng tâm: Bốn kỹ năng, bài tích hợp và đánh giá cuối học phần.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 12 trong giao tiếp thực tế.', 'Bốn kỹ năng, bài tích hợp và đánh giá cuối học phần', '["Ôn tập 150+ từ vựng HSK 1"]', '["Hệ thống hóa toàn bộ mẫu câu tuần 1–11"]', 'Tổng kiểm tra phát âm thanh điệu và đọc đoạn văn', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Tổng ôn và đánh giá (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Tổng ôn và đánh giá.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Tổng ôn và đánh giá.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 12.', 'Tình huống giao tiếp thực tế gắn với chủ đề Tổng ôn và đánh giá trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 12", "Phiếu luyện viết tuần 12"]', '["audio/zh/week-12-dialogue.mp3"]', '["Bài tập từ vựng tuần 12", "Bài tập ngữ pháp tuần 12", "Bài tập nghe hiểu tuần 12"]', 'Bài kiểm tra định kỳ cuối tuần 12 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 12.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 12.', 3);
