INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_en_02', 'mod_en_1', 'crs_en_1', 'english-beginner-week-02', 2, 'Tuần 02: Personal information', 'Personal information', 'Làm chủ chủ đề ''Personal information'' với trọng tâm: Đại từ, to be, câu hỏi cá nhân.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 2 trong giao tiếp thực tế.', 'Đại từ, to be, câu hỏi cá nhân', '["nationality", "occupation", "email", "address"]', '["Wh-questions (What/Where/Who)", "Possessive adjectives (my/your/his/her)"]', 'Trọng âm từ 2–3 âm tiết và ngữ điệu câu hỏi Wh-', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Personal information (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Personal information.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Personal information.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 2.', 'Tình huống giao tiếp thực tế gắn với chủ đề Personal information trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 02", "Phiếu luyện viết tuần 02"]', '["audio/en/week-02-dialogue.mp3"]', '["Bài tập từ vựng tuần 02", "Bài tập ngữ pháp tuần 02", "Bài tập nghe hiểu tuần 02"]', 'Bài kiểm tra định kỳ cuối tuần 02 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 02.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 03.', 3);
