INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_en_06', 'mod_en_1', 'crs_en_1', 'english-beginner-week-06', 6, 'Tuần 06: Food and shopping', 'Food and shopping', 'Làm chủ chủ đề ''Food and shopping'' với trọng tâm: Danh từ đếm được/không đếm được, yêu cầu.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 6 trong giao tiếp thực tế.', 'Danh từ đếm được/không đếm được, yêu cầu', '["receipt", "discount", "beverage", "ingredient"]', '["Countable & Uncountable nouns", "Some / Any / How much / How many"]', 'Nối âm trong câu yêu cầu lịch sự (Would you like...)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Food and shopping (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Food and shopping.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Food and shopping.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 6.', 'Tình huống giao tiếp thực tế gắn với chủ đề Food and shopping trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 06", "Phiếu luyện viết tuần 06"]', '["audio/en/week-06-dialogue.mp3"]', '["Bài tập từ vựng tuần 06", "Bài tập ngữ pháp tuần 06", "Bài tập nghe hiểu tuần 06"]', 'Bài kiểm tra định kỳ cuối tuần 06 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 06.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 07.', 3);
