INSERT OR IGNORE INTO wb_study_sessions (id, week_id, session_code, title_vi, position_in_week, duration_minutes, objectives, new_knowledge, vocabulary_json, grammar_json, pronunciation_notes, examples_json, materials_json, activities_json, short_exercises_json, comprehension_check_json, summary_text, self_study_homework, completion_condition) VALUES ('ses_en_12_1', 'wk_en_12', 'EN-W12-S1', 'Buổi 1 — Integrated assessment', 1, 45, 'Nắm vững nền tảng Integrated assessment', 'Nghe, nói, đọc, viết và đánh giá tổng hợp', '["Ôn tập 300+ từ vựng CEFR A1"]', '["Hệ thống hóa ngữ pháp tuần 1–11"]', 'Đánh giá phát âm IPA, âm cuối và trọng âm câu', '["Ví dụ 1","Ví dụ 2"]', '["Slide bài giảng","Phiếu bài tập"]', '["Nghe mẫu","Thực hành cặp","Kiểm tra nhanh"]', '["Điền từ","Sắp xếp câu"]', '["Câu hỏi kiểm tra hiểu bài"]', 'Tổng kết trọng tâm Integrated assessment.', 'Ôn tập 15 phút trên Sổ từ vựng WORD BRIDGE.', 'Hoàn thành bài tập ngắn và đạt >= 70% kiểm tra mức hiểu.');
INSERT OR IGNORE INTO wb_lessons (id, session_id, week_id, slug, title_vi, language_code, level_ref, is_public_preview, components_json, author_name, reviewer_name, reference_sources, version, review_status) VALUES ('les_en_12_1', 'ses_en_12_1', 'wk_en_12', 'english-week-12-lesson-01', 'Bài 1 (Tuần 12: Integrated assessment)', 'en', 'CEFR A1', 1, '{"objectives": "Nắm vững kiến thức cốt lõi của Tuần 12: Integrated assessment.", "coreKnowledge": "Nghe, nói, đọc, viết và đánh giá tổng hợp", "newVocabulary": ["Ôn tập 300+ từ vựng CEFR A1"], "grammar": ["Hệ thống hóa ngữ pháp tuần 1–11"], "phonetics": "Đánh giá phát âm IPA, âm cuối và trọng âm câu", "examples": ["Ví dụ ứng dụng chuẩn cho chủ đề Integrated assessment."], "context": "Bối cảnh giao tiếp thực tế cho Integrated assessment.", "listening": "Nghe đoạn mẫu chủ đề Integrated assessment và trả lời 3 câu hỏi kiểm tra ý chính.", "speaking": "Đọc theo câu mẫu với tốc độ 0.75x rồi 1.0x; tự luyện phát âm qua microphone khi chủ động bật.", "reading": "Đọc đoạn văn ngắn minh họa và gạch chân cấu trúc trọng tâm.", "writing": "Viết 5 câu hoàn chỉnh vận dụng từ vựng và ngữ pháp tuần 12.", "assessment": "Kiểm tra mức hiểu cuối bài (5 câu hỏi nhanh)."}', 'Ban Biên soạn WORD BRIDGE', 'Hội đồng Học thuật WORD BRIDGE', 'Giáo trình chuẩn WORD BRIDGE V3.0', '1.0.0', 'published');
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_ru_01', 'mod_ru_1', 'crs_ru_1', 'russian-beginner-week-01', 1, 'Tuần 01: Cyrillic alphabet', 'Cyrillic alphabet', 'Làm chủ chủ đề ''Cyrillic alphabet'' với trọng tâm: Chữ cái, âm, nhận diện chữ.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 1 trong giao tiếp thực tế.', 'Chữ cái, âm, nhận diện chữ', '["привет", "да", "нет", "спасибо"]', '["33 chữ cái Cyrillic in và viết tay", "Phân biệt chữ cái giống hình Latin"]', 'Nhận diện âm nguyên âm cứng/mềm cơ bản', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Cyrillic alphabet (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Cyrillic alphabet.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Cyrillic alphabet.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 1.', 'Tình huống giao tiếp thực tế gắn với chủ đề Cyrillic alphabet trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 01", "Phiếu luyện viết tuần 01"]', '["audio/ru/week-01-dialogue.mp3"]', '["Bài tập từ vựng tuần 01", "Bài tập ngữ pháp tuần 01", "Bài tập nghe hiểu tuần 01"]', 'Bài kiểm tra định kỳ cuối tuần 01 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 01.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 02.', 3);
