INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_ru_03', 'mod_ru_1', 'crs_ru_1', 'russian-beginner-week-03', 3, 'Tuần 03: Greetings and introductions', 'Greetings and introductions', 'Làm chủ chủ đề ''Greetings and introductions'' với trọng tâm: Chào hỏi, đại từ và động từ cơ bản.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 3 trong giao tiếp thực tế.', 'Chào hỏi, đại từ và động từ cơ bản', '["здравствуйте", "меня зовут", "очень приятно"]', '["Đại từ nhân xưng я/ты/он/она/мы/вы/они", "Cấu trúc Меня зовут..."]', 'Ngữ điệu câu chào trang trọng và thân mật', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Greetings and introductions (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Greetings and introductions.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Greetings and introductions.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 3.', 'Tình huống giao tiếp thực tế gắn với chủ đề Greetings and introductions trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 03", "Phiếu luyện viết tuần 03"]', '["audio/ru/week-03-dialogue.mp3"]', '["Bài tập từ vựng tuần 03", "Bài tập ngữ pháp tuần 03", "Bài tập nghe hiểu tuần 03"]', 'Bài kiểm tra định kỳ cuối tuần 03 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 03.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 04.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_ru_04', 'mod_ru_1', 'crs_ru_1', 'russian-beginner-week-04', 4, 'Tuần 04: Gender and nominative', 'Gender and nominative', 'Làm chủ chủ đề ''Gender and nominative'' với trọng tâm: Giống danh từ, tính từ, Cách 1.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 4 trong giao tiếp thực tế.', 'Giống danh từ, tính từ, Cách 1', '["студент", "книга", "письмо", "новый"]', '["Phân biệt 3 giống danh từ (đực, cái, trung)", "Cách 1 (Именительный падеж)"]', 'Đọc đuôi tính từ giống đực/cái/trung', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Gender and nominative (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Gender and nominative.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Gender and nominative.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 4.', 'Tình huống giao tiếp thực tế gắn với chủ đề Gender and nominative trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 04", "Phiếu luyện viết tuần 04"]', '["audio/ru/week-04-dialogue.mp3"]', '["Bài tập từ vựng tuần 04", "Bài tập ngữ pháp tuần 04", "Bài tập nghe hiểu tuần 04"]', 'Bài kiểm tra định kỳ cuối tuần 04 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 04.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 05.', 3);
