INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_ru_09', 'mod_ru_1', 'crs_ru_1', 'russian-beginner-week-09', 9, 'Tuần 09: Verbs and aspects', 'Verbs and aspects', 'Làm chủ chủ đề ''Verbs and aspects'' với trọng tâm: Động từ, nguyên thể, giới thiệu thể.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 9 trong giao tiếp thực tế.', 'Động từ, nguyên thể, giới thiệu thể', '["делать/сделать", "писать/написать", "говорить"]', '["Chia động từ nhóm I & II", "Khái niệm cặp thể chưa hoàn thành (НСВ) và hoàn thành (СВ)"]', 'Chuyển dịch trọng âm khi chia động từ', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Verbs and aspects (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Verbs and aspects.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Verbs and aspects.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 9.', 'Tình huống giao tiếp thực tế gắn với chủ đề Verbs and aspects trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 09", "Phiếu luyện viết tuần 09"]', '["audio/ru/week-09-dialogue.mp3"]', '["Bài tập từ vựng tuần 09", "Bài tập ngữ pháp tuần 09", "Bài tập nghe hiểu tuần 09"]', 'Bài kiểm tra định kỳ cuối tuần 09 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 09.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 10.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_ru_10', 'mod_ru_1', 'crs_ru_1', 'russian-beginner-week-10', 10, 'Tuần 10: Daily routine', 'Daily routine', 'Làm chủ chủ đề ''Daily routine'' với trọng tâm: Hoạt động hằng ngày, thời gian.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 10 trong giao tiếp thực tế.', 'Hoạt động hằng ngày, thời gian', '["утром", "днём", "вечером", "работать"]', '["Trạng từ chỉ buổi trong ngày", "Thì hiện tại & quá khứ cơ bản"]', 'Ngữ điệu câu trần thuật (ИК-1) và câu hỏi (ИК-3)', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Daily routine (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Daily routine.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Daily routine.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 10.', 'Tình huống giao tiếp thực tế gắn với chủ đề Daily routine trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 10", "Phiếu luyện viết tuần 10"]', '["audio/ru/week-10-dialogue.mp3"]', '["Bài tập từ vựng tuần 10", "Bài tập ngữ pháp tuần 10", "Bài tập nghe hiểu tuần 10"]', 'Bài kiểm tra định kỳ cuối tuần 10 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 10.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 11.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_ru_11', 'mod_ru_1', 'crs_ru_1', 'russian-beginner-week-11', 11, 'Tuần 11: Communication scenarios', 'Communication scenarios', 'Làm chủ chủ đề ''Communication scenarios'' với trọng tâm: Mua sắm, hỏi đường, giao tiếp.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 11 trong giao tiếp thực tế.', 'Mua sắm, hỏi đường, giao tiếp', '["сколько стоит", "извините", "где находится", "пожалуйста"]', '["Mẫu câu hỏi giá, hỏi đường và đề nghị lịch sự"]', 'Luyện phản xạ ngữ điệu câu hỏi không có từ để hỏi', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Communication scenarios (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Communication scenarios.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Communication scenarios.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 11.', 'Tình huống giao tiếp thực tế gắn với chủ đề Communication scenarios trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 11", "Phiếu luyện viết tuần 11"]', '["audio/ru/week-11-dialogue.mp3"]', '["Bài tập từ vựng tuần 11", "Bài tập ngữ pháp tuần 11", "Bài tập nghe hiểu tuần 11"]', 'Bài kiểm tra định kỳ cuối tuần 11 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 11.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 12.', 3);
INSERT OR IGNORE INTO wb_weeks (id, module_id, course_id, slug, week_number, name_vi, topic_vi, week_objectives, learning_outcomes, required_knowledge, core_vocabulary_json, core_grammar_json, pronunciation_phonetics, listening_content, speaking_content, reading_content, writing_content, application_scenario, study_materials_json, audio_refs_json, exercises_json, weekly_test_spec, passing_criteria, review_assignment, next_week_prep, sessions_count) VALUES ('wk_ru_12', 'mod_ru_1', 'crs_ru_1', 'russian-beginner-week-12', 12, 'Tuần 12: Integrated assessment', 'Integrated assessment', 'Làm chủ chủ đề ''Integrated assessment'' với trọng tâm: Nghe, nói, đọc, viết và đánh giá.', 'Người học vận dụng thành thạo từ vựng, ngữ pháp và phát âm của tuần 12 trong giao tiếp thực tế.', 'Nghe, nói, đọc, viết và đánh giá', '["Ôn tập từ vựng nền tảng TORFL ТЭУ"]', '["Hệ thống hóa Cách 1, 4, 6 và động từ"]', 'Đánh giá đọc thành tiếng chuẩn trọng âm Cyrillic', 'Bài nghe hội thoại mẫu và nghe điền từ chủ đề Integrated assessment (tốc độ 0.75x và 1.0x).', 'Luyện đọc thành tiếng, lặp lại câu mẫu và đóng vai hội thoại chủ đề Integrated assessment.', 'Đọc hiểu đoạn hội thoại ngắn và văn bản ứng dụng chủ đề Integrated assessment.', 'Viết câu hoàn chỉnh và đoạn văn ngắn (40–80 từ) áp dụng cấu trúc tuần 12.', 'Tình huống giao tiếp thực tế gắn với chủ đề Integrated assessment trong đời sống và công việc.', '["Tài liệu tóm tắt tuần 12", "Phiếu luyện viết tuần 12"]', '["audio/ru/week-12-dialogue.mp3"]', '["Bài tập từ vựng tuần 12", "Bài tập ngữ pháp tuần 12", "Bài tập nghe hiểu tuần 12"]', 'Bài kiểm tra định kỳ cuối tuần 12 (20 phút, trắc nghiệm + điền từ + viết ngắn).', 'Hoàn thành tối thiểu 2/3 buổi học trong tuần và đạt >= 70% điểm kiểm tra tuần.', 'Ôn tập flashcard ngắt quãng (SM-2) toàn bộ từ vựng tuần 12.', 'Xem trước bảng từ vựng và mục tiêu của Tuần 12.', 3);
INSERT OR IGNORE INTO wb_study_sessions (id, week_id, session_code, title_vi, position_in_week, duration_minutes, objectives, new_knowledge, vocabulary_json, grammar_json, pronunciation_notes, examples_json, materials_json, activities_json, short_exercises_json, comprehension_check_json, summary_text, self_study_homework, completion_condition) VALUES ('ses_ru_12_1', 'wk_ru_12', 'RU-W12-S1', 'Buổi 1 — Integrated assessment', 1, 45, 'Nắm vững nền tảng Integrated assessment', 'Nghe, nói, đọc, viết và đánh giá', '["Ôn tập từ vựng nền tảng TORFL ТЭУ"]', '["Hệ thống hóa Cách 1, 4, 6 và động từ"]', 'Đánh giá đọc thành tiếng chuẩn trọng âm Cyrillic', '["Ví dụ 1","Ví dụ 2"]', '["Slide bài giảng","Phiếu bài tập"]', '["Nghe mẫu","Thực hành cặp","Kiểm tra nhanh"]', '["Điền từ","Sắp xếp câu"]', '["Câu hỏi kiểm tra hiểu bài"]', 'Tổng kết trọng tâm Integrated assessment.', 'Ôn tập 15 phút trên Sổ từ vựng WORD BRIDGE.', 'Hoàn thành bài tập ngắn và đạt >= 70% kiểm tra mức hiểu.');
INSERT OR IGNORE INTO wb_lessons (id, session_id, week_id, slug, title_vi, language_code, level_ref, is_public_preview, components_json, author_name, reviewer_name, reference_sources, version, review_status) VALUES ('les_ru_12_1', 'ses_ru_12_1', 'wk_ru_12', 'russian-week-12-lesson-01', 'Bài 1 (Tuần 12: Integrated assessment)', 'ru', 'TORFL ТЭУ', 1, '{"objectives": "Nắm vững kiến thức cốt lõi của Tuần 12: Integrated assessment.", "coreKnowledge": "Nghe, nói, đọc, viết và đánh giá", "newVocabulary": ["Ôn tập từ vựng nền tảng TORFL ТЭУ"], "grammar": ["Hệ thống hóa Cách 1, 4, 6 và động từ"], "phonetics": "Đánh giá đọc thành tiếng chuẩn trọng âm Cyrillic", "examples": ["Ví dụ ứng dụng chuẩn cho chủ đề Integrated assessment."], "context": "Bối cảnh giao tiếp thực tế cho Integrated assessment.", "listening": "Nghe đoạn mẫu chủ đề Integrated assessment và trả lời 3 câu hỏi kiểm tra ý chính.", "speaking": "Đọc theo câu mẫu với tốc độ 0.75x rồi 1.0x; tự luyện phát âm qua microphone khi chủ động bật.", "reading": "Đọc đoạn văn ngắn minh họa và gạch chân cấu trúc trọng tâm.", "writing": "Viết 5 câu hoàn chỉnh vận dụng từ vựng và ngữ pháp tuần 12.", "assessment": "Kiểm tra mức hiểu cuối bài (5 câu hỏi nhanh)."}', 'Ban Biên soạn WORD BRIDGE', 'Hội đồng Học thuật WORD BRIDGE', 'Giáo trình chuẩn WORD BRIDGE V3.0', '1.0.0', 'published');

INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_zh_nihao', 'zh', 'ni-hao', '你好', 'nihao', 'nǐ hǎo', 'nǐ hǎo', '3-3 (biến điệu 2-3)', NULL, 'thán từ / cụm chào', NULL, 'xin chào', '用于打招呼的礼貌用语。', '[{"text":"你好，请问您贵姓？","vi":"Xin chào, xin hỏi quý danh của anh/chị là gì?"}]', 'Bộ Nhân (亻) + Bộ Nữ (女) & Tử (子)', 'greetings', 'HSK 1', NULL, 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_zh_haiyuntidan', 'zh', 'hai-yun-ti-dan', '海运提单', 'haiyuntidan', 'hǎiyùn tídān', 'hǎiyùn tídān', '3-4-2-1', NULL, 'danh từ chuyên ngành', NULL, 'vận đơn đường biển (Bill of Lading)', '承运人收到货物后签发给托运人的货物收据和物权凭证。', '[{"text":"请核对海运提单上的收货人信息。","vi":"Vui lòng đối chiếu thông tin người nhận hàng trên vận đơn đường biển."}]', '海(biển) + 运(vận chuyển) + 提单(vận đơn)', 'logistics', 'HSK 4', 'logistics', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_zh_shangyefapiao', 'zh', 'shang-ye-fa-piao', '商业发票', 'shangyefapiao', 'shāngyè fāpiào', 'shāngyè fāpiào', '1-4-1-4', NULL, 'danh từ chuyên ngành', NULL, 'hóa đơn thương mại (Commercial Invoice)', '出口商开立给进口商列明货物数量、单价和总金额的正式单据。', '[{"text":"报关时需要提交商业发票和装箱单。","vi":"Khi khai báo hải quan cần nộp hóa đơn thương mại và phiếu đóng gói."}]', '商业(thương mại) + 发票(hóa đơn)', 'logistics', 'HSK 4', 'logistics', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_zh_zhuangxiangdan', 'zh', 'zhuang-xiang-dan', '装箱单', 'zhuangxiangdan', 'zhuāngxiāngdān', 'zhuāngxiāngdān', '1-1-1', NULL, 'danh từ chuyên ngành', NULL, 'phiếu đóng gói (Packing List)', '详细列明每件包装内货物规格、重量和体积的单证。', '[{"text":"装箱单上的毛重和净重必须准确无误。","vi":"Trọng lượng cả bì và trọng lượng tịnh trên phiếu đóng gói phải chính xác tuyệt đối."}]', '装箱(đóng thùng) + 单(phiếu)', 'logistics', 'HSK 4', 'logistics', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_zh_yuanchandizhengshu', 'zh', 'yuan-chan-di-zheng-shu', '原产地证书', 'yuanchandizhengshu', 'yuánchǎndì zhèngshū', 'yuánchǎndì zhèngshū', '2-3-4-4-1', NULL, 'danh từ chuyên ngành', NULL, 'giấy chứng nhận xuất xứ (Certificate of Origin)', '证明进出口货物原产国或地区的官方文件。', '[{"text":"凭借原产地证书，进口商可以申请关税优惠。","vi":"Dựa vào giấy chứng nhận xuất xứ, nhà nhập khẩu có thể xin ưu đãi thuế quan."}]', '原产地(nơi xuất xứ) + 证书(giấy chứng nhận)', 'logistics', 'HSK 5', 'import-export', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_zh_baoguan', 'zh', 'bao-guan', '报关', 'baoguan', 'bàoguān', 'bàoguān', '4-1', NULL, 'động từ chuyên ngành', NULL, 'khai báo hải quan (Customs declaration)', '向海关申报进出口货物情况并办理通关手续的行为。', '[{"text":"这批货物已经在港口完成报关手续。","vi":"Lô hàng này đã hoàn tất thủ tục khai báo hải quan tại cảng."}]', '报(báo cáo) + 关(hải quan)', 'logistics', 'HSK 4', 'import-export', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_zh_gongyinglianguanli', 'zh', 'gong-ying-lian-guan-li', '供应链管理', 'gongyinglianguanli', 'gōngyìngliàn guǎnlǐ', 'gōngyìngliàn guǎnlǐ', '1-4-4-3-3', NULL, 'danh từ chuyên ngành', NULL, 'quản trị chuỗi cung ứng (Supply chain management)', '对原材料采购、生产制造到成品交付全流程的统筹管理。', '[{"text":"高效的供应链管理能显著降低物流成本。","vi":"Quản trị chuỗi cung ứng hiệu quả có thể giảm đáng kể chi phí logistics."}]', '供应链(chuỗi cung ứng) + 管理(quản lý)', 'logistics', 'HSK 5', 'logistics', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_en_schedule', 'en', 'schedule', 'schedule', 'schedule', '/ˈskedʒuːl/ (US) · /ˈʃedʒuːl/ (UK)', '/ˈskedʒuːl/', NULL, 'âm tiết 1', 'danh từ (n) / động từ (v)', NULL, 'lịch trình, thời gian biểu; lên lịch', 'A plan for carrying out a process or procedure, giving lists of intended events and times.', '[{"text":"Please check the updated delivery schedule before Friday.","vi":"Vui lòng kiểm tra lịch trình giao hàng đã cập nhật trước thứ Sáu."}]', NULL, 'daily-life', 'CEFR A2', NULL, 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_en_bill_of_lading', 'en', 'bill-of-lading', 'bill of lading', 'bill of lading', '/ˌbɪl əv ˈleɪdɪŋ/', '/ˌbɪl əv ˈleɪdɪŋ/', NULL, 'leɪd', 'danh từ chuyên ngành', NULL, 'vận đơn đường biển', 'A detailed list of a shipment of goods in the form of a receipt given by the carrier to the person consigning the goods.', '[{"text":"The consignee must present the original bill of lading to release the cargo.","vi":"Người nhận hàng phải xuất trình vận đơn gốc để giải phóng lô hàng."}]', NULL, 'logistics', 'CEFR B2', 'logistics', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_en_cloud_architecture', 'en', 'cloud-architecture', 'cloud architecture', 'cloud architecture', '/klaʊd ˈɑːrkɪtektʃər/', '/klaʊd ˈɑːrkɪtektʃər/', NULL, 'ɑːr', 'danh từ chuyên ngành', NULL, 'kiến trúc điện toán đám mây', 'The way technology components combine to build a cloud computing environment.', '[{"text":"Our team migrated the legacy monolith to a serverless cloud architecture.","vi":"Nhóm chúng tôi đã chuyển đổi hệ thống nguyên khối cũ sang kiến trúc đám mây serverless."}]', NULL, 'it-cloud', 'CEFR B2', 'it-cloud', 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_ru_privet', 'ru', 'privet', 'приве́т', 'привет', '[prʲɪˈvʲet]', '[prʲɪˈvʲet]', NULL, 'âm tiết 2 (приве́т)', 'thán từ / danh từ', 'giống đực (m)', 'xin chào (thân mật); lời chào', 'Неофициальное приветствие при встрече.', '[{"text":"Приве́т! Как у тебя́ дела́?","vi":"Chào bạn! Dạo này bạn thế nào?"}]', NULL, 'greetings', 'TORFL ТЭУ', NULL, 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_ru_kniga', 'ru', 'kniga', 'кни́га', 'книга', '[ˈknʲiɡə]', '[ˈknʲiɡə]', NULL, 'âm tiết 1 (кни́га)', 'danh từ (n)', 'giống cái (f)', 'quyển sách', 'Печатное издание в виде переплетённых листов бумаги с текстом.', '[{"text":"Я чита́ю интере́сную ру́сскую кни́гу.","vi":"Tôi đang đọc một quyển sách tiếng Nga thú vị."}]', NULL, 'education', 'TORFL ТЭУ', NULL, 'src_wb_original', 'published');
INSERT OR IGNORE INTO wb_dictionary_entries (id, language_code, slug, headword, normalized_headword, phonetic, ipa_or_pinyin, tone_pattern, stress_pattern, part_of_speech, noun_gender, meaning_vi, target_definition, examples_json, radicals_or_structure, topic, level_ref, specialized_domain, source_id, review_status) VALUES ('dict_ru_universitet', 'ru', 'universitet', 'университе́т', 'университет', '[ʊnʲɪvʲɪrsʲɪˈtʲet]', '[ʊnʲɪvʲɪrsʲɪˈtʲet]', NULL, 'âm tiết 5 (университе́т)', 'danh từ (n)', 'giống đực (m)', 'trường đại học', 'Высшее учебное заведение и научный центр.', '[{"text":"Мы у́чимся в университе́те.","vi":"Chúng tôi học tại trường đại học."}]', NULL, 'education', 'TORFL ТЭУ', NULL, 'src_wb_original', 'published');

INSERT OR IGNORE INTO wb_grammar_topics (id, language_code, slug, title_vi, level_ref, explanation_vi, structure_formula, examples_json) VALUES
  ('grm_zh_1', 'zh', 'cau-chu-vi-shi', 'Câu vị ngữ động từ 是 (shì)', 'HSK 1', 'Dùng để khẳng định danh tính, nghề nghiệp hoặc quốc tịch. Phủ định dùng 不是 (bú shì).', 'Chủ ngữ + (不)是 + Danh từ', '[{"text":"我是越南学生。","vi":"Tôi là sinh viên Việt Nam."}]'),
  ('grm_en_1', 'en', 'present-simple', 'Thì Hiện tại đơn (Present Simple)', 'CEFR A1', 'Diễn tả thói quen, lịch trình cố định và sự thật hiển nhiên.', 'S + V(s/es) / S + do/does not + V', '[{"text":"She practices listening every morning.","vi":"Cô ấy luyện nghe mỗi sáng."}]'),
  ('grm_ru_1', 'ru', 'accusative-case', 'Cách 4 Tiếng Nga (Винительный падеж)', 'TORFL ТЭУ', 'Biểu thị tân ngữ trực tiếp chịu tác động của ngoại động từ; danh từ giống cái đuôi -а/-я đổi thành -у/-ю.', 'Động từ + Danh từ (Cách 4)', '[{"text":"Я читаю книгу.","vi":"Tôi đọc quyển sách."}]');

-- 8. Question Bank, Practice Exercises & Examinations (NO CERTIFICATES)
INSERT OR IGNORE INTO wb_question_bank (id, language_code, skill, question_type, level_ref, topic, prompt_text, options_json, correct_answer_json, explanation_vi, max_score, auto_gradable) VALUES
  ('qb_zh_1', 'zh', 'vocabulary', 'single_choice', 'HSK 4', 'logistics', 'Thuật ngữ tiếng Trung nào có nghĩa là "Vận đơn đường biển (Bill of Lading)"?', '["海运提单","商业发票","装箱单","原产地证书"]', '"海运提单"', '海运提单 (hǎiyùn tídān) là vận đơn đường biển.', 1.0, 1),
  ('qb_zh_2', 'zh', 'grammar', 'single_choice', 'HSK 1', 'introduction', 'Chọn câu đúng để nói "Tôi là sinh viên Việt Nam":', '["我是越南学生。","我越南是学生。","是越南我学生。"]', '"我是越南学生。"', 'Cấu trúc chuẩn: Chủ ngữ + 是 + Định ngữ + Danh từ.', 1.0, 1),
  ('qb_en_1', 'en', 'grammar', 'single_choice', 'CEFR A1', 'daily-life', 'Choose the correct verb form: "She ___ English every evening."', '["study","studies","studying","studied"]', '"studies"', 'Chủ ngữ ngôi thứ 3 số ít (She) ở thì hiện tại đơn chia là studies.', 1.0, 1),
  ('qb_en_2', 'en', 'writing', 'essay', 'CEFR B1', 'business', 'Write a short professional email (80–120 words) confirming a shipment schedule.', '[]', NULL, 'Bài viết tự luận được chấm theo rubric mạch lạc, ngữ pháp và độ tự nhiên; hệ thống không chấm điểm giả.', 10.0, 0),
  ('qb_ru_1', 'ru', 'grammar', 'single_choice', 'TORFL ТЭУ', 'cases', 'Chọn dạng Cách 4 đúng của từ "книга" trong câu "Я читаю ___":', '["книга","книгу","книге","книги"]', '"книгу"', 'Danh từ giống cái kết thúc bằng -а đổi sang -у ở Cách 4.', 1.0, 1);

INSERT OR IGNORE INTO wb_practice_exercises (id, slug, language_code, skill, title_vi, level_ref, topic, instructions_vi, question_ids_json, rubric_summary_vi) VALUES
  ('pex_zh_voc_1', 'zh-logistics-vocab-drill', 'zh', 'vocabulary', 'Luyện từ vựng Tiếng Trung Logistics cơ bản', 'HSK 4', 'logistics', 'Chọn thuật ngữ tiếng Trung tương ứng với chứng từ xuất nhập khẩu.', '["qb_zh_1","qb_zh_2"]', 'Tự động chấm trắc nghiệm chính xác theo đáp án chuẩn.'),
  ('pex_en_grm_1', 'en-present-simple-drill', 'en', 'grammar', 'Luyện ngữ pháp Thì Hiện tại đơn', 'CEFR A1', 'daily-life', 'Hoàn thành câu bằng dạng động từ đúng.', '["qb_en_1"]', 'Tự động chấm kèm giải thích chi tiết bằng tiếng Việt.'),
  ('pex_en_wrt_1', 'en-email-writing-practice', 'en', 'writing', 'Luyện viết Email xác nhận lịch giao hàng', 'CEFR B1', 'business', 'Viết email ngắn 80–120 từ theo văn phong chuyên nghiệp.', '["qb_en_2"]', 'Đánh giá theo rubric 4 tiêu chí (không cấp điểm tự động giả).'),
  ('pex_ru_grm_1', 'ru-accusative-case-drill', 'ru', 'grammar', 'Luyện tập Cách 4 Tiếng Nga', 'TORFL ТЭУ', 'cases', 'Chọn dạng biến cách chính xác của danh từ làm tân ngữ trực tiếp.', '["qb_ru_1"]', 'Tự động chấm kèm giải thích quy tắc biến cách.');

INSERT OR IGNORE INTO wb_examinations (id, slug, language_code, title_vi, framework_reference, level_ref, skills_json, topic, duration_minutes, instructions_vi, question_ids_json, scoring_scale_json, passing_threshold) VALUES
  ('exm_zh_hsk1', 'hsk-1-reference-diagnostic', 'zh', 'Đề đánh giá tham chiếu HSK 1 (Tiếng Trung)', 'Tham chiếu HSK 1', 'HSK 1', '["vocabulary","grammar","reading"]', 'Tổng hợp sơ cấp', 30, 'Đọc kỹ từng câu hỏi và lưu nháp tự động trong quá trình làm bài. Lưu ý: WORD BRIDGE không cấp chứng chỉ.', '["qb_zh_1","qb_zh_2"]', '{"scale":"0-100","pass":60}', 60.0),
  ('exm_en_a1', 'cefr-a1-reference-diagnostic', 'en', 'Đề đánh giá tham chiếu CEFR A1 (Tiếng Anh)', 'Tham chiếu CEFR A1', 'CEFR A1', '["grammar","reading"]', 'Tổng hợp A1', 30, 'Làm bài độc lập trong thời gian quy định. Kết quả chỉ mang tính tham chiếu học tập, không phải chứng chỉ.', '["qb_en_1"]', '{"scale":"0-100","pass":60}', 60.0),
  ('exm_ru_teu', 'torfl-teu-reference-diagnostic', 'ru', 'Đề đánh giá tham chiếu TORFL ТЭУ (Tiếng Nga)', 'Tham chiếu TORFL ТЭУ', 'TORFL ТЭУ', '["grammar","reading"]', 'Tổng hợp ТЭУ', 30, 'Kiểm tra kiến thức Cyrillic và biến cách cơ bản. WORD BRIDGE không cấp chứng chỉ chính thức.', '["qb_ru_1"]', '{"scale":"0-100","pass":60}', 60.0);

